    // ─────────────── ۳۴: گرگ و میش بت‌ها ───────────────
    private fun story34() = StoryContent(
        storyId = "adv_twilight_of_the_idols",
        chapters = listOf(
            StoryChapter(
                number = 1, title = "The Hammer", titlePersian = "چکش",
                paragraphs = listOf(
                    StoryParagraph("In the quiet hours before dawn, a philosopher sat alone with his thoughts.", "در ساعت‌های آرام پیش از سپیده‌دم، فیلسوفی تنها با اندیشه‌هایش نشسته بود."),
                    StoryParagraph("He had spent his life questioning every idol that humanity had erected.", "تمام عمرش را صرف پرسشگری از هر بتی کرده بود که بشریت برپا کرده بود."),
                    StoryParagraph("He had learned that the greatest truths are hidden beneath the most beloved illusions.", "آموخته بود که بزرگ‌ترین حقیقت‌ها زیر محبوب‌ترین توهمات پنهان‌اند."),
                    StoryParagraph("What is a belief, he wondered, but a habit of the soul that has forgotten its origins?", "اندیشید: باور چیست جز عادتی روحی که خاستگاه خود را از یاد برده است؟"),
                    StoryParagraph("The idols of the age stood tall in the marketplace, demanding reverence from every passerby.", "بت‌های این عصر در بازار بلند قامت ایستاده بودند و از هر رهگذری احترام می‌طلبیدند."),
                    StoryParagraph("Some idols were made of gold, others of virtue, but all were made of human longing.", "برخی بت‌ها از طلا ساخته شده بودند، برخی از فضیلت، اما همه از اشتیاق انسانی."),
                    StoryParagraph("The philosopher lifted his hammer, not to destroy, but to test the sound of each hollow thing.", "فیلسوف چکش خود را بلند کرد، نه برای نابودی، بلکه برای آزمودن صدای هر چیز توخالی."),
                    StoryParagraph("Where the sound rang true, he bowed; where it echoed empty, he struck again.", "جایی که صدا حقیقی بود، سر تعظیم فرود آورد؛ جایی که پوچ می‌پیچید، دوباره کوبید."),
                    StoryParagraph("Truth, he had come to understand, is not given but forged in the fire of doubt.", "دریافته بود که حقیقت داده نمی‌شود، بلکه در آتش شک ساخته می‌شود."),
                    StoryParagraph("The crowd gathered, some curious, some hostile, some indifferent to the fate of their gods.", "جمعیت گرد آمد، برخی کنجکاو، برخی خصمانه، برخی بی‌تفاوت به سرنوشت خدایانشان."),
                    StoryParagraph("He spoke to them not of what to believe, but of how to question.", "با آنان نه از آنچه باید باور کرد سخن گفت، بلکه از چگونگی پرسیدن."),
                    StoryParagraph("Is it not strange, he asked, that we fear our own questions more than we fear the answers?", "پرسید: آیا شگفت‌آور نیست که ما از پرسش‌های خود بیشتر از پاسخ‌ها می‌ترسیم؟"),
                    StoryParagraph("A young man in the crowd stepped forward and said he had been taught never to doubt.", "جوانی از میان جمعیت پیش آمد و گفت به او آموخته‌اند که هرگز شک نکند."),
                    StoryParagraph("And who taught you? the philosopher asked. A man, or a fear dressed in a man's clothes?", "فیلسوف پرسید: چه کسی آموخت؟ انسانی، یا ترسی که جامه انسان پوشیده بود؟"),
                    StoryParagraph("The young man fell silent, for he did not know which answer was more terrible.", "جوان ساکت شد، زیرا نمی‌دانست کدام پاسخ هولناک‌تر است."),
                    StoryParagraph("Doubt is not the enemy of truth, the philosopher said, but its midwife.", "فیلسوف گفت: شک دشمن حقیقت نیست، بلکه قابله آن است."),
                    StoryParagraph("Every great certainty must pass through the narrow gate of uncertainty.", "هر یقین بزرگی باید از دروازه تنگ عدم یقین بگذرد."),
                    StoryParagraph("Those who never doubt have never truly believed; they have only obeyed.", "آنان که هرگز شک نمی‌کنند، هرگز به‌راستی باور نکرده‌اند؛ تنها اطاعت کرده‌اند."),
                    StoryParagraph("As the sun rose over the marketplace, the idols cast long shadows upon the earth.", "هنگامی که خورشید بر بازار طلوع کرد، بت‌ها سایه‌های بلند بر زمین افکندند."),
                    StoryParagraph("But shadows, the philosopher reminded them, are born of light and prove its existence.", "اما فیلسوف یادآور شد که سایه‌ها از نور زاده می‌شوند و وجود آن را اثبات می‌کنند."),
                    StoryParagraph("Even the darkest idol stands only because some light has touched it.", "حتی تاریک‌ترین بت تنها به این دلیل ایستاده که نوری آن را لمس کرده است."),
                    StoryParagraph("So do not curse the shadow, but seek the light that gives it shape.", "پس سایه را نفرین مکن، بلکه نوری را بجوی که به آن شکل می‌بخشد."),
                    StoryParagraph("When the crowd dispersed, each carried a small hammer in their hearts.", "هنگامی که جمعیت پراکنده شد، هر یک چکشی کوچک در قلب خود حمل می‌کرد."),
                    StoryParagraph("Some would use it to destroy, others to build, but all would use it to question.", "برخی از آن برای نابودی استفاده می‌کردند، برخی برای ساختن، اما همه برای پرسیدن."),
                    StoryParagraph("And the philosopher walked home alone, content that he had planted doubt where certainty had reigned.", "فیلسوف تنها به خانه بازگشت، خشنود که در جایی که یقین حکومت می‌کرد، شک کاشته بود."),
                    StoryParagraph("For doubt, he knew, is the seed from which all authentic faith must grow.", "زیرا می‌دانست شک بذری است که هر ایمان اصیلی باید از آن رشد کند."),
                    StoryParagraph("Without the winter of questioning, there can be no spring of understanding.", "بدون زمستان پرسیدن، بهاری برای فهمیدن وجود ندارد."),
                    StoryParagraph("He wrote in his journal that night: the hammer is not for breaking idols, but for hearing their ring.", "آن شب در دفتر خود نوشت: چکش برای شکستن بت‌ها نیست، برای شنیدن صدای آن‌هاست."),
                    StoryParagraph("And in that ring, the wise man hears the truth of what he worships.", "و در آن صدا، مرد خردمند حقیقت آنچه را می‌پرستد می‌شنود."),
                    StoryParagraph("The idols that ring true shall remain; the hollow ones shall crumble of their own accord.", "بت‌هایی که صدای حقیقی می‌دهند باقی می‌مانند؛ توخالی‌ها خودبه‌خود فرو می‌ریزند."),
                    StoryParagraph("For time itself is the greatest hammer, and it spares nothing false.", "زیرا زمان خود بزرگ‌ترین چکش است و چیزی دروغین را نمی‌بخشد."),
                    StoryParagraph("In the end, only truth has the strength to survive its own questioning.", "در پایان، تنها حقیقت توانِ بقا در برابر پرسشگری خود را دارد."),
                    StoryParagraph("The philosopher slept, and in his dreams he saw a world where every idol had been tested.", "فیلسوف به خواب رفت و در رؤیاهایش جهانی دید که در آن هر بتی آزموده شده بود."),
                    StoryParagraph("It was a world both poorer and richer, having lost its illusions and gained its freedom.", "جهانی هم فقیرتر و هم غنی‌تر بود؛ توهماتش را از دست داده و آزادی‌اش را یافته بود."),
                    StoryParagraph("This, he understood, was the true twilight of the idols, not their death but their judgment.", "فهمید که این همان گرگ و میش راستین بت‌هاست؛ نه مرگشان، بلکه داوری‌شان."),
                    StoryParagraph("And in that judgment, humanity would finally learn to stand without them.", "و در آن داوری، بشریت سرانجام می‌آموخت که بدون آنان بایستد."),
                    StoryParagraph("For we are not made weak by the loss of our gods, but strong by the finding of ourselves.", "زیرا با از دست دادن خدایانمان ضعیف نمی‌شویم، بلکه با یافتن خودمان نیرومند می‌شویم."),
                    StoryParagraph("The morning came, and with it, the courage to ask the first question.", "صبح آمد و با آن، شهامت پرسیدن نخستین پرسش."),
                    StoryParagraph("What do I truly believe, and why do I believe it?", "من واقعاً به چه چیزی باور دارم و چرا به آن باور دارم؟"),
                    StoryParagraph("The answer, the philosopher knew, would take a lifetime to find.", "فیلسوف می‌دانست که یافتن پاسخ، یک عمر زمان می‌برد."),
                    StoryParagraph("But a lifetime spent in honest questioning is worth more than an eternity of blind certainty.", "اما عمری که در پرسش صادقانه سپری شود، از ابدیتی از یقین کور ارزشمندتر است.")
                )
            ),
            StoryChapter(
                number = 2, title = "The Four Great Errors", titlePersian = "چهار خطای بزرگ",
                paragraphs = listOf(
                    StoryParagraph("There are four great errors, the philosopher wrote, that have enslaved the human mind.", "فیلسوف نوشت: چهار خطای بزرگ وجود دارد که ذهن بشر را به بردگی گرفته است."),
                    StoryParagraph("The first error is the confusion of cause and effect.", "نخستین خطا، اشتباه گرفتن علت و معلول است."),
                    StoryParagraph("We believe we act because we have a motive, but the motive is invented after the act.", "ما باور داریم که به دلیل انگیزه عمل می‌کنیم، اما انگیزه پس از عمل ساخته می‌شود."),
                    StoryParagraph("The second error is the belief in false causality.", "دومین خطا، باور به علیت کاذب است."),
                    StoryParagraph("We attribute our actions to our will, as if the will were a free agent within us.", "ما اعمال خود را به اراده نسبت می‌دهیم، گویی اراده عاملی آزاد در درون ماست."),
                    StoryParagraph("But the will, too, is a fiction invented to explain what we do not understand.", "اما اراده نیز افسانه‌ای است که برای توضیح آنچه نمی‌فهمیم ساخته شده."),
                    StoryParagraph("The third error is the belief in imaginary causes.", "سومین خطا، باور به علل خیالی است."),
                    StoryParagraph("We explain the unknown by inventing spirits, gods, and invisible forces.", "ناشناخته را با ساختن ارواح، خدایان و نیروهای نامرئی توضیح می‌دهیم."),
                    StoryParagraph("The fourth error is the belief in free will.", "چهارمین خطا، باور به اراده آزاد است."),
                    StoryParagraph("We imagine ourselves as authors of our deeds, when we are merely their stage.", "خود را نویسنده کردار خویش می‌پنداریم، در حالی که تنها صحنه نمایش آن هستیم."),
                    StoryParagraph("These four errors, taken together, form the fabric of what we call morality.", "این چهار خطا، در کنار هم، بافت آنچه را که اخلاق می‌نامیم شکل می‌دهند."),
                    StoryParagraph("And morality, in turn, has been used to judge, condemn, and punish.", "و اخلاق نیز به نوبه خود برای قضاوت، محکوم کردن و مجازات به کار رفته است."),
                    StoryParagraph("But who gave us the right to judge? the philosopher asked.", "اما فیلسوف پرسید: چه کسی به ما حق قضاوت داده است؟"),
                    StoryParagraph("Only those who claim to know the will of God, which is to say, the unknowable.", "تنها کسانی که ادعا می‌کنند اراده خدا را می‌دانند، یعنی نادانستنی را."),
                    StoryParagraph("The judge and the criminal are made of the same clay, shaped by the same blind forces.", "قاضی و مجرم از یک گِل ساخته شده‌اند و توسط همان نیروهای کور شکل گرفته‌اند."),
                    StoryParagraph("To condemn another is to condemn oneself; to forgive another is to forgive oneself.", "محکوم کردن دیگری، محکوم کردن خویش است؛ بخشیدن دیگری، بخشیدن خویش."),
                    StoryParagraph("This is not weakness, but the highest form of understanding.", "این ضعف نیست، بلکه والاترین شکل فهم است."),
                    StoryParagraph("For only those who understand everything can forgive everything.", "زیرا تنها کسانی که همه چیز را می‌فهمند می‌توانند همه چیز را ببخشند."),
                    StoryParagraph("The philosopher did not preach forgiveness as a virtue, but as a consequence of knowledge.", "فیلسوف بخشش را به‌عنوان فضیلت موعظه نکرد، بلکه به‌عنوان پیامد دانش."),
                    StoryParagraph("When you truly see why a man acts as he does, judgment dissolves like mist in the sun.", "هنگامی که واقعاً ببینی چرا انسانی آن‌گونه عمل می‌کند، قضاوت چون مه در برابر خورشید ناپدید می‌شود."),
                    StoryParagraph("But this does not mean that all actions are equal, or that nothing matters.", "اما این بدان معنا نیست که همه اعمال یکسانند یا هیچ چیز مهم نیست."),
                    StoryParagraph("It means that our judgments, too, are part of the same chain of causes we judge.", "بلکه بدان معناست که قضاوت‌های ما نیز بخشی از همان زنجیره عللی هستند که آن را قضاوت می‌کنیم."),
                    StoryParagraph("There is no outside position from which to judge the world; we are always within it.", "هیچ موضعی بیرون از جهان برای قضاوت آن وجود ندارد؛ ما همیشه درون آنیم."),
                    StoryParagraph("And from within, the only honest attitude is humility.", "و از درون، تنها نگرش صادقانه، فروتنی است."),
                    StoryParagraph("Not the humility of the slave, but the humility of the seeker who knows how little he knows.", "نه فروتنی برد، بلکه فروتنی جوینده‌ای که می‌داند چه اندک می‌داند."),
                    StoryParagraph("Such humility is the beginning of all wisdom, and its end.", "چنین فروتنی آغاز تمام خرد است و پایانش."),
                    StoryParagraph("The philosopher wrote these four errors on a stone and placed it at the crossroads.", "فیلسوف این چهار خطا را بر سنگی نوشت و آن را در چهارراه گذاشت."),
                    StoryParagraph("Travelers would stop, read, and either laugh or weep.", "رهگذران می‌ایستادند، می‌خواندند و یا می‌خندیدند یا می‌گریستند."),
                    StoryParagraph("Those who laughed had understood; those who wept had understood even more.", "آنان که خندیدند فهمیده بودند؛ آنان که گریستند بیشتر فهمیده بودند."),
                    StoryParagraph("For the truth is both liberating and terrifying, and only the brave can bear it.", "زیرا حقیقت هم رهایی‌بخش است و هم هراس‌آور، و تنها شجاعان می‌توانند آن را تحمل کنند."),
                    StoryParagraph("But bear it we must, if we are to live as free beings rather than comfortable slaves.", "اما باید آن را تحمل کنیم، اگر می‌خواهیم همچون موجوداتی آزاد و نه بردگانی راحت زندگی کنیم."),
                    StoryParagraph("Freedom is not a gift but a burden, and one that few are willing to carry.", "آزادی هدیه نیست، باری است که اندکی حاضران به حمل آن‌اند."),
                    StoryParagraph("Yet it is the only burden worth carrying, for it is the only one that makes us human.", "با این حال، تنها باری است که ارزش حمل کردن دارد، زیرا تنها باری است که ما را انسان می‌کند."),
                    StoryParagraph("The stone remained at the crossroads for many years, growing weathered by rain and wind.", "سنگ سال‌ها در چهارراه ماند و با باران و باد فرسوده شد."),
                    StoryParagraph("But the words engraved upon it never faded, for truth is not erased by time.", "اما کلمات حک‌شده بر آن هرگز محو نشد، زیرا حقیقت با گذر زمان پاک نمی‌شود."),
                    StoryParagraph("And travelers still stop there, still read, still laugh or weep.", "و رهگذران هنوز آنجا می‌ایستند، هنوز می‌خوانند، هنوز می‌خندند یا می‌گریند."),
                    StoryParagraph("For the four great errors are reborn in every generation, and must be overcome anew.", "زیرا چهار خطای بزرگ در هر نسلی دوباره متولد می‌شوند و باید از نو چیره شوند."),
                    StoryParagraph("This is the eternal task of philosophy, and the eternal hope of humanity.", "این وظیفه جاوید فلسفه است و امید جاوید بشریت."),
                    StoryParagraph("Not to possess the truth, but to keep asking the questions that lead toward it.", "نه در اختیار داشتن حقیقت، بلکه پیوسته پرسیدن پرسش‌هایی که به سوی آن راه می‌برند."),
                    StoryParagraph("The philosopher, wherever he was, smiled, knowing that the work would never be finished.", "فیلسوف، هر جا که بود، لبخند زد و دانست که این کار هرگز به پایان نخواهد رسید."),
                    StoryParagraph("And that, precisely, was its beauty.", "و این، دقیقاً، زیبایی آن بود.")
                )
            ),
            StoryChapter(
                number = 3, title = "The Will to Power", titlePersian = "اراده معطوف به قدرت",
                paragraphs = listOf(
                    StoryParagraph("What drives a living thing? the philosopher asked. Not pleasure, not survival, but the will to power.", "فیلسوف پرسید: چه چیزی موجود زنده را به پیش می‌راند؟ نه لذت، نه بقا، بلکه اراده معطوف به قدرت."),
                    StoryParagraph("Every creature seeks to expand, to grow, to overcome resistance.", "هر موجودی در پی گسترش، رشد و چیره شدن بر مقاومت است."),
                    StoryParagraph("Even the smallest blade of grass pushes through stone to reach the light.", "حتی کوچک‌ترین تیغه چمن از سنگ می‌شکافد تا به نور برسد."),
                    StoryParagraph("This striving is not a choice; it is the essence of life itself.", "این تلاش یک انتخاب نیست؛ ذات خود زندگی است."),
                    StoryParagraph("The weak call it selfishness; the strong call it nature.", "ضعیفان آن را خودخواهی می‌نامند؛ نیرومندان آن را طبیعت."),
                    StoryParagraph("But both are merely naming what they cannot escape.", "اما هر دو تنها چیزی را نام‌گذاری می‌کنند که از آن نمی‌توانند بگریزند."),
                    StoryParagraph("The will to power is not the will to dominate others, but the will to surpass oneself.", "اراده معطوف به قدرت، اراده تسلط بر دیگران نیست، اراده فراتر رفتن از خویش است."),
                    StoryParagraph("It is the artist struggling to perfect his craft, the athlete pushing beyond his limits.", "این همان هنرمندی است که برای کمال هنرش می‌کوشد، ورزشکاری که فراتر از مرزهایش می‌رود."),
                    StoryParagraph("It is the child learning to walk, falling and rising a hundred times.", "این همان کودکی است که راه رفتن می‌آموزد، صد بار می‌افتد و برمی‌خیزد."),
                    StoryParagraph("Every act of creation is an act of self-overcoming.", "هر عمل آفرینش، عملی از فراتر رفتن از خویش است."),
                    StoryParagraph("But there is also a will to power that degrades, that seeks to dominate rather than to elevate.", "اما اراده معطوف به قدرتی نیز هست که فرو می‌کاهد، که در پی سلطه است نه برکشیدن."),
                    StoryParagraph("This is not true power, but the mask of weakness.", "این قدرت راستین نیست، نقاب ضعف است."),
                    StoryParagraph("For only the weak need to dominate; the strong elevate others without fear.", "زیرا تنها ضعیفان به سلطه نیاز دارند؛ نیرومندان دیگران را بدون ترس برمی‌کشند."),
                    StoryParagraph("The philosopher distinguished between master morality and slave morality.", "فیلسوف میان اخلاق ارباب و اخلاق برده تمایز قائل شد."),
                    StoryParagraph("Master morality says: good is what is noble, what is strong, what is life-affirming.", "اخلاق ارباب می‌گوید: خوب آن است که نجیب است، آن که نیرومند است، آن که زندگی‌ستا است."),
                    StoryParagraph("Slave morality says: good is what is humble, what is obedient, what denies life.", "اخلاق برده می‌گوید: خوب آن است که فروتن است، آن که فرمانبردار است، آن که زندگی را انکار می‌کند."),
                    StoryParagraph("The first creates values; the second resents them.", "نخستین ارزش‌ها را می‌آفریند؛ دومین به آن‌ها کینه می‌ورزد."),
                    StoryParagraph("The history of morality, the philosopher claimed, is the history of slave morality's triumph.", "فیلسوف ادعا کرد که تاریخ اخلاق، تاریخ پیروزی اخلاق برده است."),
                    StoryParagraph("But this triumph is not the end; it is a stage to be overcome.", "اما این پیروزی پایان نیست؛ مرحله‌ای است که باید از آن فراتر رفت."),
                    StoryParagraph("For the future, he prophesied, belongs to those who can create new values.", "زیرا او پیش‌بینی کرد که آینده از آنِ کسانی است که می‌توانند ارزش‌های نو بیافرینند."),
                    StoryParagraph("Not values given by gods or priests, but values forged in the fire of one's own existence.", "نه ارزش‌هایی که خدایان یا کاهنان داده‌اند، بلکه ارزش‌هایی که در آتش هستی خویش ساخته شده‌اند."),
                    StoryParagraph("Such a creator is what the philosopher called the overman.", "چنین آفریننده‌ای همان است که فیلسوف او را اَبَرانسان نامید."),
                    StoryParagraph("Not a master race, as later readers would wrongly claim, but a master of oneself.", "نه نژاد ارباب، آن‌گونه که خوانندگان بعدی به نادرست ادعا کردند، بلکه ارباب خویشتن."),
                    StoryParagraph("The overman is the one who has overcome his own pettiness, his own resentment, his own fear.", "اَبَرانسان کسی است که بر فرومایگی خود، بر کینه خود، بر ترس خود چیره شده است."),
                    StoryParagraph("He does not need heaven, because he has learned to love the earth.", "او به بهشت نیاز ندارد، زیرا آموخته که زمین را دوست بدارد."),
                    StoryParagraph("He does not need salvation, because he has learned to embrace his own becoming.", "او به رستگاری نیاز ندارد، زیرا آموخته که شدنِ خویش را در آغوش بگیرد."),
                    StoryParagraph("This is not arrogance, but the deepest responsibility.", "این خودبینی نیست، بلکه عمیق‌ترین مسئولیت است."),
                    StoryParagraph("For to become who you are requires courage beyond measure.", "زیرا شدن به آنچه هستی، شهامتی بی‌اندازه می‌طلبد."),
                    StoryParagraph("It requires facing your own darkness and not turning away.", "می‌طلبد که با تاریکی خویش روبه‌رو شوی و روی برنگردانی."),
                    StoryParagraph("It requires saying yes to life in all its terror and all its beauty.", "می‌طلبد که به زندگی در تمام هراس و تمام زیبایی‌اش آری بگویی."),
                    StoryParagraph("The philosopher called this amor fati, the love of fate.", "فیلسوف این را آمور فاتی نامید، عشق به سرنوشت."),
                    StoryParagraph("Not resignation, not passive acceptance, but joyful affirmation of what is.", "نه تسلیم، نه پذیرش منفعلانه، بلکه تأیید شادمانه آنچه هست."),
                    StoryParagraph("To love what is, including what is painful, is the highest achievement of the human spirit.", "دوست داشتن آنچه هست، از جمله آنچه دردناک است، والاترین دستاورد روح انسانی است."),
                    StoryParagraph("For only such a love can transform suffering into meaning.", "زیرا تنها چنین عشقی می‌تواند رنج را به معنا بدل کند."),
                    StoryParagraph("The philosopher wrote these words and felt a great peace descend upon him.", "فیلسوف این کلمات را نوشت و آرامشی بزرگ را حس کرد که بر او نازل می‌شد."),
                    StoryParagraph("For he had found, if not happiness, then something greater: purpose.", "زیرا اگر نه شادی، چیزی بزرگ‌تر یافته بود: هدف."),
                    StoryParagraph("The will to power, rightly understood, is the will to become fully oneself.", "اراده معطوف به قدرت، اگر درست فهمیده شود، اراده به تمام‌خود شدن است."),
                    StoryParagraph("And in that becoming, all beings find their highest joy.", "و در آن شدن، همه موجودات والاترین شادی خود را می‌یابند."),
                    StoryParagraph("Not the joy of the satisfied animal, but the joy of the creator who has made something worthy.", "نه شادی حیوان سیرشده، بلکه شادی آفریننده‌ای که چیزی شایسته ساخته است."),
                    StoryParagraph("This is the joy the philosopher wished for all who would follow him.", "این شادی‌ای است که فیلسوف برای همه کسانی که از او پیروی می‌کردند آرزو داشت."),
                    StoryParagraph("And with that wish, he closed his book and went out into the sunlight.", "و با آن آرزو، کتابش را بست و به روشنایی خورشید بیرون رفت.")
                )
            ),
            StoryChapter(
                number = 4, title = "The Eternal Return", titlePersian = "بازگشت جاودان",
                paragraphs = listOf(
                    StoryParagraph("What if, the philosopher asked, you were condemned to live this same life again, endlessly?", "فیلسوف پرسید: اگر محکوم می‌شدی که همین زندگی را بی‌پایان دوباره زندگی کنی چه؟"),
                    StoryParagraph("Every joy, every sorrow, every moment of boredom, returning again and again forever.", "هر شادی، هر اندوه، هر لحظه کسالت، بی‌پایان بازگردند."),
                    StoryParagraph("Would you curse the demon who spoke these words, or would you bless him?", "آیا دیوی را که این سخنان گفت نفرین می‌کردی یا او را برکت می‌دادی؟"),
                    StoryParagraph("This question, the philosopher said, is the heaviest weight.", "فیلسوف گفت: این پرسش، سنگین‌ترین بار است."),
                    StoryParagraph("For it demands that we examine our lives not by their moments of joy, but by their entirety.", "زیرا می‌طلبد که زندگی خود را نه با لحظه‌های شادی، بلکه به تمامی بررسی کنیم."),
                    StoryParagraph("Not what you have enjoyed, but what you would be willing to relive forever.", "نه آنچه از آن لذت برده‌ای، بلکه آنچه حاضری تا ابد دوباره زندگی کنی."),
                    StoryParagraph("The person who can say yes to this question has achieved the highest affirmation.", "کسی که بتواند به این پرسش آری بگوید، والاترین تأیید را یافته است."),
                    StoryParagraph("The person who says no has revealed the places where they have not yet lived fully.", "کسی که نه بگوید، جاهایی را آشکار کرده که هنوز به تمامی زندگی نکرده است."),
                    StoryParagraph("These places are not sins to be confessed, but tasks to be undertaken.", "این جاها گناهانی نیستند که اعتراف شوند، بلکه تکالیفی هستند که باید انجام شوند."),
                    StoryParagraph("The eternal return is not a doctrine to be believed, but a test to be passed.", "بازگشت جاودان عقیده‌ای نیست که باور شود، بلکه آزمونی است که باید گذرانده شود."),
                    StoryParagraph("It is the philosophical equivalent of the artist's question: would you sign this work?", "این معادل فلسفی پرسش هنرمند است: آیا این اثر را امضا می‌کردی؟"),
                    StoryParagraph("For your life is your greatest work, and you are its sole author.", "زیرا زندگی تو بزرگ‌ترین اثر توست و تو تنها نویسنده آن هستی."),
                    StoryParagraph("But if you would not sign it, you are free to rewrite it, starting now.", "اما اگر آن را امضا نمی‌کردی، آزادی از همین حالا آن را بازنویسی کنی."),
                    StoryParagraph("The eternal return, rightly understood, is not a curse but a gift.", "بازگشت جاودان، اگر درست فهمیده شود، نفرین نیست بلکه هدیه است."),
                    StoryParagraph("It is the gift of taking this life seriously, of knowing that every moment matters.", "این هدیه جدی گرفتن این زندگی است، دانستن اینکه هر لحظه اهمیت دارد."),
                    StoryParagraph("For if everything returns, then nothing is trivial.", "زیرا اگر همه چیز بازگردد، هیچ چیز بی‌اهمیت نیست."),
                    StoryParagraph("Every kind word, every act of courage, every moment of attention, becomes eternal.", "هر کلمه مهربان، هر عمل شجاعت، هر لحظه توجه، جاودان می‌شود."),
                    StoryParagraph("And every cruelty, every cowardice, every moment of neglect, becomes eternal too.", "و هر ظلم، هر بزدلی، هر لحظه غفلت نیز جاودان می‌شود."),
                    StoryParagraph("This is terrifying, but it is also liberating.", "این هراس‌آور است، اما رهایی‌بخش نیز هست."),
                    StoryParagraph("For it means that nothing we do is wasted, and nothing is beyond redemption.", "زیرا بدان معناست که هیچ کاری از ما هدر نمی‌رود و هیچ چیز فراتر از رستگاری نیست."),
                    StoryParagraph("Each moment is both a culmination and a beginning.", "هر لحظه هم اوج است و هم آغاز."),
                    StoryParagraph("The philosopher called this the innocence of becoming.", "فیلسوف این را بی‌گناهی شدن نامید."),
                    StoryParagraph("Not the innocence of the child who has not yet acted, but the innocence of the sage who has acted fully.", "نه بی‌گناهی کودکی که هنوز عمل نکرده، بلکه بی‌گناهی خردمندی که به تمامی عمل کرده است."),
                    StoryParagraph("For such a one, there is no guilt, only learning.", "برای چنین کسی، گناهی نیست، تنها یادگیری است."),
                    StoryParagraph("No punishment, only consequence.", "نه مجازات، تنها پیامد."),
                    StoryParagraph("No hell, only the recognition of what one has done.", "نه دوزخ، تنها شناخت آنچه انجام داده‌ای."),
                    StoryParagraph("This is the deepest freedom: to be responsible without being guilty.", "این عمیق‌ترین آزادی است: مسئول بودن بدون گناهکار بودن."),
                    StoryParagraph("To own one's actions fully, and yet to remain at peace.", "به تمامی مالک اعمال خویش بودن و در عین حال در آرامش ماندن."),
                    StoryParagraph("The philosopher knew that few would understand this, and fewer would live it.", "فیلسوف می‌دانست که اندکی این را خواهند فهمید و اندک‌تری آن را زندگی خواهند کرد."),
                    StoryParagraph("But for those few, the eternal return would be not a burden but a wingspan.", "اما برای آن اندک، بازگشت جاودان بار نخواهد بود، بال گشودن خواهد بود."),
                    StoryParagraph("It would lift them above the petty concerns that enslave most humans.", "آنان را فراتر از دلواپسی‌های خردی می‌برد که بیشتر انسان‌ها را به بردگی می‌کشد."),
                    StoryParagraph("It would give them the courage to live as if every moment were the last and the first.", "به آنان شهامت می‌بخشید تا چنان زندگی کنند که گویی هر لحظه آخرین و نخستین است."),
                    StoryParagraph("And in that courage, they would find a joy that nothing could take away.", "و در آن شهامت، شادی‌ای می‌یافتند که هیچ چیز نمی‌توانست از آنان بگیرد."),
                    StoryParagraph("Not the joy of circumstance, but the joy of being itself.", "نه شادی شرایط، بلکه شادی خودِ بودن."),
                    StoryParagraph("This joy, the philosopher said, is the highest thing a human can attain.", "فیلسوف گفت: این شادی، والاترین چیزی است که انسان می‌تواند به آن دست یابد."),
                    StoryParagraph("It is worth more than all the pleasures of the world, for it does not depend on them.", "از تمام لذت‌های جهان ارزشمندتر است، زیرا به آن‌ها وابسته نیست."),
                    StoryParagraph("It is the joy of one who has said yes to life, fully and forever.", "شادی کسی است که به زندگی آری گفته، به تمامی و برای همیشه."),
                    StoryParagraph("And to such a one, even death loses its sting.", "و برای چنین کسی، حتی مرگ نیش خود را از دست می‌دهد."),
                    StoryParagraph("For the one who has lived fully has nothing left to fear.", "زیرا کسی که به تمامی زیسته، چیزی برای ترسیدن باقی ندارد."),
                    StoryParagraph("The philosopher wrote these words and set down his pen.", "فیلسوف این کلمات را نوشت و قلم خود را زمین گذاشت."),
                    StoryParagraph("He looked out the window at the endless sky and smiled.", "از پنجره به آسمان بی‌پایان نگریست و لبخند زد."),
                    StoryParagraph("For he had glimpsed, if only for a moment, the eternal return of all things.", "زیرا اگر تنها برای لحظه‌ای، بازگشت جاودان همه چیز را دیده بود.")
                )
            ),
            StoryChapter(
                number = 5, title = "Beyond Good and Evil", titlePersian = "فراسوی نیک و بد",
                paragraphs = listOf(
                    StoryParagraph("Beyond good and evil, the philosopher wrote, lies the realm of the truly free spirit.", "فیلسوف نوشت: فراسوی نیک و بد، قلمرو روح راستین آزاد قرار دارد."),
                    StoryParagraph("Not beyond morality as such, but beyond the morality that has been imposed upon us.", "نه فراسوی اخلاق به‌عنوان چنین، بلکه فراسوی اخلاقی که بر ما تحمیل شده است."),
                    StoryParagraph("For there are two kinds of morality: the one we choose and the one we inherit.", "زیرا دو نوع اخلاق وجود دارد: آن که برمی‌گزینیم و آن که به ارث می‌بریم."),
                    StoryParagraph("The first is freedom; the second is slavery.", "نخستین آزادی است؛ دومین بردگی."),
                    StoryParagraph("Most people never distinguish between them, and so believe themselves moral when they are merely obedient.", "بیشتر مردم هرگز میان آن دو تمایز قائل نمی‌شوند و خود را اخلاقی می‌پندارند در حالی که فرمانبردارند."),
                    StoryParagraph("But true morality, the philosopher insisted, must be created by each individual.", "اما فیلسوف اصرار داشت که اخلاق راستین باید توسط هر فرد آفریده شود."),
                    StoryParagraph("It cannot be handed down from parent to child, from priest to congregation, from state to citizen.", "نمی‌توان آن را از والد به فرزند، از کاهن به جماعت، از دولت به شهروند سپرد."),
                    StoryParagraph("For what is handed down is always someone else's morality, never one's own.", "زیرا آنچه سپرده می‌شود همیشه اخلاق دیگری است، هرگز اخلاق خود."),
                    StoryParagraph("This does not mean that all moralities are equal, or that anything goes.", "این بدان معنا نیست که همه اخلاق‌ها یکسانند یا هر چیزی مجاز است."),
                    StoryParagraph("It means that the test of a morality is not its age or its authority, but its fruits.", "بلکه بدان معناست که آزمون یک اخلاق نه قدمت آن است و نه اقتدارش، بلکه میوه‌هایش."),
                    StoryParagraph("Does it make those who follow it stronger, freer, more alive?", "آیا پیروان خود را نیرومندتر، آزادتر، زنده‌تر می‌کند؟"),
                    StoryParagraph("Or does it make them weaker, more obedient, more dead?", "یا آنان را ضعیف‌تر، فرمانبردارتر، مرده‌تر می‌کند؟"),
                    StoryParagraph("By this test, the philosopher judged all moralities, ancient and modern alike.", "فیلسوف با این آزمون همه اخلاق‌ها را داوری کرد، هم کهن و هم نو."),
                    StoryParagraph("And he found most of them wanting, for most of them were built on fear.", "و بیشتر آن‌ها را ناکافی یافت، زیرا بیشترشان بر ترس بنا شده بودند."),
                    StoryParagraph("Fear of punishment, fear of shame, fear of the other, fear of oneself.", "ترس از مجازات، ترس از شرم، ترس از دیگری، ترس از خویش."),
                    StoryParagraph("But a morality built on fear, he said, is no morality at all.", "اما او گفت اخلاقی که بر ترس بنا شده، اصلاً اخلاق نیست."),
                    StoryParagraph("It is merely cowardice dressed in virtue's robes.", "تنها بزدلی است که جامه فضیلت پوشیده."),
                    StoryParagraph("True morality is built on love, on affirmation, on the joy of creation.", "اخلاق راستین بر عشق بنا شده، بر تأیید، بر شادی آفرینش."),
                    StoryParagraph("It says yes to life, not because life is easy, but because life is worthy.", "به زندگی آری می‌گوید، نه از آن رو که زندگی آسان است، بلکه از آن رو که زندگی شایسته است."),
                    StoryParagraph("It does not avoid suffering, but embraces it as the price of greatness.", "از رنج نمی‌گریزد، بلکه آن را به‌عنوان بهای بزرگی در آغوش می‌گیرد."),
                    StoryParagraph("For everything great, the philosopher wrote, has been bought with suffering.", "زیرا فیلسوف نوشت که هر چیز بزرگی با رنج خریداری شده است."),
                    StoryParagraph("Not suffering for its own sake, but suffering in service of something greater than oneself.", "نه رنج به‌خاطر خودش، بلکه رنج در خدمت چیزی بزرگ‌تر از خویش."),
                    StoryParagraph("This is the difference between the martyr and the hero.", "این تفاوت میان شهید و قهرمان است."),
                    StoryParagraph("The martyr dies for a cause he did not choose; the hero dies for a cause he did.", "شهید برای هدفی می‌میرد که برنگزیده؛ قهرمان برای هدفی می‌میرد که برگزیده."),
                    StoryParagraph("The martyr is a victim; the hero is a free being.", "شهید قربانی است؛ قهرمان موجودی آزاد."),
                    StoryParagraph("And only the free being, the philosopher insisted, can truly be moral.", "و فیلسوف اصرار داشت که تنها موجود آزاد می‌تواند به‌راستی اخلاقی باشد."),
                    StoryParagraph("For morality without freedom is not morality; it is merely mechanics.", "زیرا اخلاق بدون آزادی اخلاق نیست؛ تنها مکانیزم است."),
                    StoryParagraph("The wheel does not choose to turn; it simply turns. But a human chooses.", "چرخ نمی‌گزیند که بچرخد؛ تنها می‌چرخد. اما انسان می‌گزیند."),
                    StoryParagraph("And in that choosing, the human becomes what he is.", "و در آن گزینش، انسان آنچه هست می‌شود."),
                    StoryParagraph("The philosopher called this self-creation, the highest art.", "فیلسوف این را خودآفرینی نامید، والاترین هنر."),
                    StoryParagraph("Not the art of painting on canvas or writing on paper, but the art of sculpting one's own soul.", "نه هنر نقاشی بر بوم یا نوشتن بر کاغذ، بلکه هنر تراشیدن روح خویش."),
                    StoryParagraph("Every choice is a chisel stroke; every day a new block of marble.", "هر انتخاب یک ضربه قلم است؛ هر روز یک بلوک مرمر نو."),
                    StoryParagraph("And at the end of life, one sees what one has made of oneself.", "و در پایان زندگی، آنچه از خویش ساخته‌ای می‌بینی."),
                    StoryParagraph("This seeing, the philosopher said, is the only judgment that matters.", "فیلسوف گفت: این دیدن، تنها داوری‌ای است که اهمیت دارد."),
                    StoryParagraph("Not the judgment of gods or of other humans, but the judgment of one's own eyes.", "نه داوری خدایان یا دیگر انسان‌ها، بلکه داوری چشمان خود."),
                    StoryParagraph("Can you look at what you have made and call it good?", "آیا می‌توانی به آنچه ساخته‌ای بنگری و آن را خوب بخوانی؟"),
                    StoryParagraph("If yes, you are free; if no, you have work to do.", "اگر آری، آزادی؛ اگر نه، کاری برای انجام دادن داری."),
                    StoryParagraph("But the work itself, the philosopher reminded, is the joy.", "اما فیلسوف یادآور شد که خودِ کار، شادی است."),
                    StoryParagraph("Not the finished sculpture, but the sculpting.", "نه مجسمه تمام‌شده، بلکه مجسمه‌سازی."),
                    StoryParagraph("Not the destination, but the journey.", "نه مقصد، بلکه سفر."),
                    StoryParagraph("And the journey, for those who travel it fully, never ends.", "و سفر، برای آنان که آن را به تمامی می‌پیمایند، هرگز پایان نمی‌یابد.")
                )
            ),
            StoryChapter(
                number = 6, title = "The Higher Man", titlePersian = "انسان برتر",
                paragraphs = listOf(
                    StoryParagraph("The higher man, the philosopher wrote, is not a master of others but a master of himself.", "فیلسوف نوشت: انسان برتر، ارباب دیگران نیست، ارباب خویش است."),
                    StoryParagraph("He does not seek power over others, but power over his own passions.", "او در پی قدرت بر دیگران نیست، بلکه قدرت بر احساسات خویش است."),
                    StoryParagraph("He does not avoid suffering, but transforms it into wisdom.", "از رنج نمی‌گریزد، بلکه آن را به خرد بدل می‌کند."),
                    StoryParagraph("He does not fear solitude, but embraces it as the school of greatness.", "از تنهایی نمی‌هراسد، بلکه آن را به‌عنوان مکتب بزرگی در آغوش می‌گیرد."),
                    StoryParagraph("For only in solitude can one hear the voice of one's own soul.", "زیرا تنها در تنهایی می‌توان صدای روح خویش را شنید."),
                    StoryParagraph("The crowd drowns that voice with its noise; the higher man knows to seek silence.", "جمعیت آن صدا را با همهمه خود غرق می‌کند؛ انسان برتر می‌داند که سکوت را بجوید."),
                    StoryParagraph("Yet he does not despise the crowd, for he knows he once belonged to it.", "با این حال جمعیت را خوار نمی‌دارد، زیرا می‌داند روزی خود از آن بوده است."),
                    StoryParagraph("And he knows that some among the crowd may yet rise.", "و می‌داند که شاید برخی از میان جمعیت برخیزند."),
                    StoryParagraph("To them, he offers not commands but examples.", "به آنان نه فرمان می‌دهد بلکه نمونه ارائه می‌کند."),
                    StoryParagraph("For the higher man teaches not by words but by his very being.", "زیرا انسان برتر نه با کلمات بلکه با وجود خود تعلیم می‌دهد."),
                    StoryParagraph("His life is his teaching, his actions his sermon.", "زندگی‌اش تعلیم اوست، کردارش موعظه‌اش."),
                    StoryParagraph("He does not seek disciples, for he knows each must find his own way.", "او در پی مرید نیست، زیرا می‌داند هر کس باید راه خویش را بیابد."),
                    StoryParagraph("He walks his path alone, but leaves footprints that others may follow.", "او تنها راه خویش را می‌پیماید، اما ردپاهایی به جا می‌گذارد که دیگران دنبال کنند."),
                    StoryParagraph("The higher man is not born, the philosopher insisted, but made.", "فیلسوف اصرار داشت که انسان برتر زاده نمی‌شود، بلکه ساخته می‌شود."),
                    StoryParagraph("Made through discipline, through suffering, through the long labor of self-overcoming.", "از طریق انضباط ساخته می‌شود، از طریق رنج، از طریق کار دراز خودفراتر رفتن."),
                    StoryParagraph("No one becomes higher by accident; it is always a choice, renewed daily.", "هیچ‌کس به تصادف برتر نمی‌شود؛ همیشه گزینشی است که هر روز تجدید می‌شود."),
                    StoryParagraph("The choice to face what is difficult rather than what is easy.", "گزینش رویارویی با آنچه دشوار است، نه آنچه آسان."),
                    StoryParagraph("The choice to speak truth rather than comfortable lies.", "گزینش گفتن حقیقت، نه دروغ‌های راحت."),
                    StoryParagraph("The choice to create rather than to consume.", "گزینش آفریدن، نه مصرف کردن."),
                    StoryParagraph("These choices, made a thousand times, form the higher man.", "این گزینش‌ها، هزار بار انجام‌شده، انسان برتر را شکل می‌دهند."),
                    StoryParagraph("But the higher man is not a finished product; he is always in the making.", "اما انسان برتر محصول تمام‌شده نیست؛ همواره در حال ساخته شدن است."),
                    StoryParagraph("He remains a bridge, as the philosopher said, between the animal and the overman.", "همان‌گونه که فیلسوف گفت، او پلی باقی می‌ماند میان حیوان و اَبَرانسان."),
                    StoryParagraph("A rope stretched over an abyss, dangerous but glorious.", "طنابی کشیده بر پرتگاهی، خطرناک اما شکوهمند."),
                    StoryParagraph("What is great in man, the philosopher wrote, is that he is a bridge and not a goal.", "فیلسوف نوشت: آنچه در انسان بزرگ است، این است که پل است نه هدف."),
                    StoryParagraph("What can be loved in man is that he is an overture and a going under.", "آنچه در انسان می‌توان دوست داشت این است که او پیش‌درآمد و فرورفتنی است."),
                    StoryParagraph("The higher man loves his going under, for he knows it is also a going over.", "انسان برتر فرورفتن خود را دوست می‌دارد، زیرا می‌داند که گذشتن نیز هست."),
                    StoryParagraph("He does not cling to life, nor fear death, for both are part of the same journey.", "به زندگی نمی‌چسبد و از مرگ نمی‌هراسد، زیرا هر دو بخشی از همان سفرند."),
                    StoryParagraph("He lives each moment fully, as if it were his last and his first.", "هر لحظه را به تمامی زندگی می‌کند، چنان که گویی آخرین و نخستین لحظه‌اش است."),
                    StoryParagraph("And in that fullness, he finds a peace that passes all understanding.", "و در آن پُری، آرامشی می‌یابد که فراتر از همه فهم است."),
                    StoryParagraph("Not the peace of the grave, but the peace of the mountain peak.", "نه آرامش گور، بلکه آرامش قله کوه."),
                    StoryParagraph("The peace that comes from having climbed, from having seen, from having become.", "آرامشی که از صعود کردن می‌آید، از دیدن، از شدن."),
                    StoryParagraph("The higher man stands on that peak, alone but not lonely.", "انسان برتر بر آن قله می‌ایستد، تنها اما نه دل‌گیر."),
                    StoryParagraph("For he is at one with all that is, and all that is, is good.", "زیرا با تمام آنچه هست یکی است، و تمام آنچه هست، خوب است."),
                    StoryParagraph("This is the final teaching of the philosopher: to love what is.", "این تعلیم نهایی فیلسوف است: دوست داشتن آنچه هست."),
                    StoryParagraph("Not because it is perfect, but because it is real.", "نه از آن رو که کامل است، بلکه از آن رو که واقعی است."),
                    StoryParagraph("And reality, in all its terror and beauty, is worthy of our love.", "و واقعیت، در تمام هراس و زیبایی‌اش، شایسته عشق ماست."),
                    StoryParagraph("The philosopher wrote these last words and set down his pen for the final time.", "فیلسوف این آخرین کلمات را نوشت و برای آخرین بار قلم خود را زمین گذاشت."),
                    StoryParagraph("He had done his work, planted his seeds, lit his fires.", "او کار خود را کرده بود، بذرهایش را کاشته بود، آتش‌هایش را برافروخته بود."),
                    StoryParagraph("What would grow from them, he could not know.", "نمی‌توانست بداند از آن‌ها چه خواهد رویید."),
                    StoryParagraph("But he knew that growth itself was certain, as certain as the eternal return.", "اما می‌دانست که خودِ روییدن حتمی است، به‌حتمیِ بازگشت جاودان."),
                    StoryParagraph("And with that certainty, he closed his eyes and welcomed the night.", "و با آن یقین، چشمانش را بست و به شب خوش‌آمد گفت.")
                )
            )
        )
    )

