        chapters = listOf(
            StoryChapter(
                number = 1, title = "The Chestnut Tree", titlePersian = "درخت شاه‌بلوط",
                paragraphs = listOf(
                    StoryParagraph("Antoine sat in the public garden, staring at the roots of a chestnut tree.", "آنتوان در باغ عمومی نشسته بود و به ریشه‌های یک درخت شاه‌بلوط خیره شده بود."),
                    StoryParagraph("Something had changed, though he could not say what.", "چیزی تغییر کرده بود، هرچند نمی‌توانست بگوید چه."),
                    StoryParagraph("The world had always been there, familiar and reliable, but now it seemed strange.", "جهان همیشه آنجا بود، آشنا و قابل اعتماد، اما اکنون غریب به نظر می‌رسید."),
                    StoryParagraph("The roots were black, knotted, almost obscene in their raw existence.", "ریشه‌ها سیاه، گره‌خورده، تقریباً وقیح در وجود خام خود بودند."),
                    StoryParagraph("They existed, that was all, and their existence was overwhelming.", "آن‌ها وجود داشتند، همین و بس، و وجودشان طاقت‌فرسا بود."),
                    StoryParagraph("Antoine felt a wave of nausea rise in him, not from his stomach but from his very being.", "آنتوان موجی از تهوع را در خود حس کرد، نه از معده‌اش بلکه از هستی خویش."),
                    StoryParagraph("This was the first time he had truly seen existence, stripped of all meaning.", "این نخستین بار بود که او وجود را به‌راستی دیده بود، بی‌هیچ معنا."),
                    StoryParagraph("Usually, we see things through the veil of their uses, their names, their purposes.", "معمولاً ما چیزها را از پشت پرده کاربردها، نام‌ها و اهدافشان می‌بینیم."),
                    StoryParagraph("But sometimes the veil tears, and we see things as they are.", "اما گاهی پرده می‌درد و چیزها را آن‌گونه که هستند می‌بینیم."),
                    StoryParagraph("And what they are, Antoine realized, is simply there.", "و آنچه هستند، آنتوان دریافت، تنها آنجاست."),
                    StoryParagraph("No reason, no necessity, no purpose, just existence.", "نه دلیلی، نه ضرورتی، نه هدفی، تنها وجود."),
                    StoryParagraph("The chestnut tree was not beautiful, was not ugly, was not useful or useless.", "درخت شاه‌بلوط نه زیبا بود، نه زشت، نه مفید و نه بی‌فایده."),
                    StoryParagraph("It was simply there, absurdly, inexplicably, undeniably there.", "تنها آنجا بود، به‌پوچی، به‌بی‌دلیلی، انکارناپذیر آنجا."),
                    StoryParagraph("And Antoine was there too, equally absurd, equally without reason.", "و آنتوان نیز آنجا بود، به همان پوچی، به همان بی‌دلیلی."),
                    StoryParagraph("This was what he would later call the fundamental absurdity of existence.", "این همان بود که بعدها پوچی بنیادین وجود نامید."),
                    StoryParagraph("Not a philosophical theory, but an experience, a felt revelation.", "نه یک نظریه فلسفی، بلکه یک تجربه، یک مکاشفه محسوس."),
                    StoryParagraph("The experience left him shaken, unable to return to his ordinary life.", "این تجربه او را لرزانده بود، ناتوان از بازگشت به زندگی معمول."),
                    StoryParagraph("For once you have seen existence bare, you cannot unsee it.", "زیرا هنگامی که وجود را برهنه دیده باشی، نمی‌توانی نبینی."),
                    StoryParagraph("The veil, once torn, does not mend.", "پرده، چون درید، دیگر ترمیم نمی‌شود."),
                    StoryParagraph("Antoine left the garden and walked through the streets of the city.", "آنتوان باغ را ترک کرد و در خیابان‌های شهر قدم زد."),
                    StoryParagraph("But everywhere he looked, he saw the same absurd existence.", "اما هر جا که نگریست، همان وجود پوچ را دید."),
                    StoryParagraph("In the faces of strangers, in the stones of buildings, in the very air he breathed.", "در چهره غریبه‌ها، در سنگ‌های ساختمان‌ها، در همان هوایی که نفس می‌کشید."),
                    StoryParagraph("Everything was too much, too present, too real.", "همه چیز زیادی بود، زیادی حاضر، زیادی واقعی."),
                    StoryParagraph("And yet, paradoxically, nothing mattered.", "و با این حال، به‌تناقض، هیچ چیز مهم نبود."),
                    StoryParagraph("If nothing has inherent meaning, then no action is more important than another.", "اگر هیچ چیز معنای ذاتی ندارد، پس هیچ عملی از دیگری مهم‌تر نیست."),
                    StoryParagraph("Antoine found this thought both terrifying and freeing.", "آنتوان این اندیشه را هم هراس‌آور و هم رهایی‌بخش یافت."),
                    StoryParagraph("Terrifying because it stripped away all comfort.", "هراس‌آور زیرا تمام تسلی را برمی‌کند."),
                    StoryParagraph("Freeing because it opened the door to authentic choice.", "رهایی‌بخش زیرا دروازه گزینش اصیل را می‌گشاید."),
                    StoryParagraph("If nothing matters by nature, then we are free to decide what matters.", "اگر هیچ چیز به‌طبیعت مهم نیست، پس آزادیم تصمیم بگیریم چه چیزی مهم است."),
                    StoryParagraph("This freedom, Antoine understood, is the burden and the gift of being human.", "آنتوان فهمید که این آزادی، بار و هدیه انسان بودن است."),
                    StoryParagraph("We are condemned to be free, as he would later write.", "همان‌گونه که بعدها نوشت، ما محکوم به آزادی هستیم."),
                    StoryParagraph("Condemned because we cannot escape it; free because we can create.", "محکوم زیرا نمی‌توانیم از آن بگریزیم؛ آزاد زیرا می‌توانیم بیافرینیم."),
                    StoryParagraph("And what we create, in the absence of given meaning, is ourselves.", "و آنچه در غیاب معنای داده‌شده می‌آفرینیم، خودمان هستیم."),
                    StoryParagraph("Antoine walked home slowly, his mind full of these thoughts.", "آنتوان آهسته به خانه بازگشت، ذهنش پر از این اندیشه‌ها."),
                    StoryParagraph("He did not yet know what he would do with them.", "هنوز نمی‌دانست با آن‌ها چه خواهد کرد."),
                    StoryParagraph("But he knew that he could never go back to his old life.", "اما می‌دانست که هرگز نمی‌تواند به زندگی پیشین بازگردد."),
                    StoryParagraph("The nausea had changed him, and it would not let him rest.", "تهوع او را تغییر داده بود و به او اجازه نمی‌داد بیارامد."),
                    StoryParagraph("For the rest of his life, he would struggle with this revelation.", "برای باقی عمرش، با این مکاشفه دست‌وپنجه نرم می‌کرد."),
                    StoryParagraph("Sometimes he would forget it, and live as others live.", "گاهی آن را فراموش می‌کرد و همچون دیگران زندگی می‌کرد."),
                    StoryParagraph("But it always returned, as surely as the chestnut tree returned each spring.", "اما همیشه بازمی‌گشت، به‌همان یقینی که درخت شاه‌بلوط هر بهار بازمی‌گشت."),
                    StoryParagraph("And each time, he would feel again the nausea of existence.", "و هر بار، دوباره تهوع وجود را حس می‌کرد."),
                    StoryParagraph("Until, at last, he learned to make peace with it.", "تا آنکه، سرانجام، آموخت با آن صلح کند.")
                )
            ),
            StoryChapter(
                number = 2, title = "The Bouville Café", titlePersian = "کافه بوویل",
                paragraphs = listOf(
                    StoryParagraph("In the café, Antoine watched the waiter move among the tables.", "در کافه، آنتوان گارسون را دید که میان میزها می‌رفت و می‌آمد."),
                    StoryParagraph("The waiter's movements were precise, practiced, mechanical.", "حرکات گارسون دقیق، تمرین‌شده، مکانیکی بود."),
